'use client'

import * as React from 'react'
import { cn } from '@/lib/utils'
import { Checkbox } from '@/registry/satin/ui/checkbox'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * Table, 1:1 with the uiKit `Table` set (3411:21610) and its parts: table/header (3410:17835),
 * table/row (3410:18040), table/cell (3409:17760), table/headerCell (3409:17734) and
 * table/checkboxCell (3409:17703). A real `<table>`.
 *
 * - Frame: bg/card, 1px border-subtle, radius-xl, clipped.
 * - Header row: component/table-header fill, 1px border-subtle under it. Header cells pad
 *   4 / 8 / 4 / 4 around a label button (8px sides, 3px top and bottom, radius-md, medium
 *   13/18, text-muted); hover tints the button bg-hover. Sortable headers cycle
 *   none → asc → desc with a 14px arrow 10px after the label, and set aria-sort.
 * - Cells: 12 left, 10 right, 8 top and bottom, at least 40 high, regular 13/19.5, clipped
 *   with an ellipsis. Chips and other nodes sit in a row 4px apart.
 * - Checkbox column: 8px left padding, no right padding; the header box selects all.
 * - zebra: every second row on component/table-zebra.
 * - Row hover lifts the row: bg-hover, 1px border-strong edge, radius-xl, shadow sm.
 * - overflow="fit": columns are proportional (`width` is an fr weight). overflow="scroll":
 *   columns keep their pixel `width`, the first column stays in place, a 64px fade marks
 *   the clipped edge and a 6px scrollbar (bg-muted track, border-strong thumb) sits below.
 *
 * The row edge is drawn with inset shadows on the cells, since table rows can't take a
 * border radius. `data-force="hover"` on a `<tr>` shows the hover state.
 */

export type Sort = { key: string; direction: 'asc' | 'desc' } | null

/** A row: any object with a string `id`. Interfaces work too; no index signature needed. */
export type Row = { id: string }

interface ColumnBase<R extends Row> {
  header: React.ReactNode
  /** fr weight with overflow="fit" (default 1), pixels with overflow="scroll" (default 160). */
  width?: number
  sortable?: boolean
  align?: 'left' | 'right'
}

/**
 * A column. Its `key` names a field of the row and the cell shows that field, so a typo in `key`
 * is a type error. A computed column (a field the row doesn't have) gives its own `cell`.
 */
export type Column<R extends Row = Row> =
  | (ColumnBase<R> & {
      key: keyof R & string
      /** Renders the cell; defaults to the row's value at `key`. */
      cell?: (row: R) => React.ReactNode
    })
  | (ColumnBase<R> & { key: string; cell: (row: R) => React.ReactNode })

export interface TableProps<R extends Row = Row> extends Omit<React.ComponentProps<'div'>, 'children'> {
  columns: Column<R>[]
  rows: R[]
  selectable?: boolean
  zebra?: boolean
  overflow?: 'fit' | 'scroll'
  /** Called with the new sort; rows are sorted by value unless `manualSort` is set. */
  onSortChange?: (sort: Sort) => void
  defaultSort?: Sort
  /** Leave rows in the order given (sort them yourself in onSortChange). */
  manualSort?: boolean
  selected?: string[]
  onSelectedChange?: (ids: string[]) => void
  /** Accessible name of the table. */
  label?: string
}

/** The Figma sort arrow, 14 at 1.09. Pointing down for descending. */
function SortIcon({ direction }: { direction: 'asc' | 'desc' }) {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 14 14"
      fill="none"
      aria-hidden
      className={cn('sa:shrink-0 sa:text-text-muted', direction === 'desc' && 'sa:rotate-180')}
    >
      <path
        d="M7.00025 11.4515L7.00025 2.54852M11.2044 6.7527L7.00025 2.54852L2.79608 6.7527"
        stroke="currentColor"
        strokeWidth="1.09375"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

// Hover styles for the cells of a hovered (or data-force="hover") row. Written out in full so
// Tailwind sees every class.
const cellHover = {
  first: [
    'sa:group-hover/row:rounded-l-xl sa:group-hover/row:bg-bg-hover sa:group-hover/row:[box-shadow:inset_1px_0_0_var(--border-strong),inset_0_1px_0_var(--border-strong),inset_0_-1px_0_var(--border-strong)]',
    'sa:group-data-[force=hover]/row:rounded-l-xl sa:group-data-[force=hover]/row:bg-bg-hover sa:group-data-[force=hover]/row:[box-shadow:inset_1px_0_0_var(--border-strong),inset_0_1px_0_var(--border-strong),inset_0_-1px_0_var(--border-strong)]',
  ].join(' '),
  middle: [
    'sa:group-hover/row:bg-bg-hover sa:group-hover/row:[box-shadow:inset_0_1px_0_var(--border-strong),inset_0_-1px_0_var(--border-strong)]',
    'sa:group-data-[force=hover]/row:bg-bg-hover sa:group-data-[force=hover]/row:[box-shadow:inset_0_1px_0_var(--border-strong),inset_0_-1px_0_var(--border-strong)]',
  ].join(' '),
  last: [
    'sa:group-hover/row:rounded-r-xl sa:group-hover/row:bg-bg-hover sa:group-hover/row:[box-shadow:inset_-1px_0_0_var(--border-strong),inset_0_1px_0_var(--border-strong),inset_0_-1px_0_var(--border-strong)]',
    'sa:group-data-[force=hover]/row:rounded-r-xl sa:group-data-[force=hover]/row:bg-bg-hover sa:group-data-[force=hover]/row:[box-shadow:inset_-1px_0_0_var(--border-strong),inset_0_1px_0_var(--border-strong),inset_0_-1px_0_var(--border-strong)]',
  ].join(' '),
  only: [
    'sa:group-hover/row:rounded-xl sa:group-hover/row:bg-bg-hover sa:group-hover/row:[box-shadow:inset_0_0_0_1px_var(--border-strong)]',
    'sa:group-data-[force=hover]/row:rounded-xl sa:group-data-[force=hover]/row:bg-bg-hover sa:group-data-[force=hover]/row:[box-shadow:inset_0_0_0_1px_var(--border-strong)]',
  ].join(' '),
}

// Shadow sm under a hovered row (Figma: 0 1 1 and 0 1 1.5 in effect/shadow-sm).
const rowHover =
  'sa:hover:[filter:drop-shadow(0_1px_1px_var(--effect-shadow-sm))_drop-shadow(0_1px_1.5px_var(--effect-shadow-sm))] sa:data-[force=hover]:[filter:drop-shadow(0_1px_1px_var(--effect-shadow-sm))_drop-shadow(0_1px_1.5px_var(--effect-shadow-sm))]'

function compare(a: unknown, b: unknown) {
  if (typeof a === 'number' && typeof b === 'number') return a - b
  return String(a ?? '').localeCompare(String(b ?? ''), undefined, { numeric: true })
}

export function Table<R extends Row = Row>({
  columns,
  rows,
  selectable = false,
  zebra = false,
  overflow = 'fit',
  onSortChange,
  defaultSort = null,
  manualSort = false,
  selected: selectedProp,
  onSelectedChange,
  label,
  className,
  ...props
}: TableProps<R>) {
  const labels = useSatinLabels()
  const [sort, setSort] = React.useState<Sort>(defaultSort)
  const [selectedState, setSelectedState] = React.useState<string[]>([])
  const selected = selectedProp ?? selectedState
  const setSelected = (ids: string[]) => {
    if (selectedProp === undefined) setSelectedState(ids)
    onSelectedChange?.(ids)
  }

  const cycleSort = (key: string) => {
    const next: Sort =
      sort?.key !== key ? { key, direction: 'asc' } : sort.direction === 'asc' ? { key, direction: 'desc' } : null
    setSort(next)
    onSortChange?.(next)
  }

  const sortedRows = React.useMemo(() => {
    if (!sort || manualSort) return rows
    const field = (r: R) => (r as Record<string, unknown>)[sort.key]
    const s = [...rows].sort((a, b) => compare(field(a), field(b)))
    return sort.direction === 'desc' ? s.reverse() : s
  }, [rows, sort, manualSort])

  const scroll = overflow === 'scroll'
  const allSelected = rows.length > 0 && rows.every((r) => selected.includes(r.id))
  const someSelected = !allSelected && rows.some((r) => selected.includes(r.id))

  // Column widths: fr weights as percentages, or fixed pixels when scrolling.
  const totalFr = columns.reduce((n, c) => n + (c.width ?? 1), 0)
  const colWidth = (c: Column<R>) => (scroll ? `${c.width ?? 160}px` : `${((c.width ?? 1) / totalFr) * 100}%`)
  const tableWidth = scroll ? columns.reduce((n, c) => n + (c.width ?? 160), selectable ? 24 : 0) : undefined

  // The custom scrollbar and the edge fade follow the viewport's scroll position.
  const viewport = React.useRef<HTMLDivElement>(null)
  const [bar, setBar] = React.useState({ size: 1, offset: 0, atEnd: true })
  React.useEffect(() => {
    const el = viewport.current
    if (!scroll || !el) return
    const update = () => {
      const size = el.clientWidth / el.scrollWidth
      const max = el.scrollWidth - el.clientWidth
      setBar({ size, offset: max > 0 ? el.scrollLeft / el.scrollWidth : 0, atEnd: el.scrollLeft >= max - 1 })
    }
    update()
    el.addEventListener('scroll', update, { passive: true })
    const ro = new ResizeObserver(update)
    ro.observe(el)
    return () => {
      el.removeEventListener('scroll', update)
      ro.disconnect()
    }
  }, [scroll, columns, rows])

  // The leading column(s) stay put while the rest scroll.
  const stickyFirst = (bg: string) => (scroll ? cn('sa:sticky sa:z-[1]', bg) : '')
  const firstDataLeft = selectable ? 'sa:left-6' : 'sa:left-0'

  const cellPosition = (index: number, count: number) =>
    count === 1 ? cellHover.only : index === 0 ? cellHover.first : index === count - 1 ? cellHover.last : cellHover.middle
  const cellCount = columns.length + (selectable ? 1 : 0)

  const table = (
    <table
      aria-label={label}
      className="sa:w-full sa:table-fixed sa:border-separate sa:border-spacing-0 sa:text-left"
      // With overflow="fit" the columns keep at least 120px each, so a phone scrolls instead of crushing them.
      style={tableWidth ? { width: tableWidth, minWidth: '100%' } : { minWidth: columns.length * 120 + (selectable ? 24 : 0) }}
    >
      <colgroup>
        {selectable && <col style={{ width: 24 }} />}
        {columns.map((c) => (
          <col key={c.key} style={{ width: colWidth(c) }} />
        ))}
      </colgroup>
      <thead>
        <tr className="sa:bg-component-table-header">
          {selectable && (
            <th
              scope="col"
              className={cn('sa:border-b sa:border-border-subtle sa:py-2 sa:pl-2 sa:align-middle', stickyFirst('sa:left-0 sa:bg-component-table-header'))}
            >
              <Checkbox
                aria-label={labels.selectAllRows}
                checked={allSelected ? true : someSelected ? 'indeterminate' : false}
                onCheckedChange={(v) => setSelected(v === true ? rows.map((r) => r.id) : [])}
                className="sa:align-middle"
              />
            </th>
          )}
          {columns.map((c, i) => {
            const active = sort?.key === c.key ? sort.direction : undefined
            const labelClass =
              'sa:inline-flex sa:max-w-full sa:items-center sa:gap-2.5 sa:overflow-hidden sa:rounded-md sa:px-2 sa:py-[3px] sa:text-sm sa:leading-[18px] sa:font-medium sa:whitespace-nowrap sa:text-text-muted'
            return (
              <th
                key={c.key}
                scope="col"
                aria-sort={c.sortable ? (active === 'asc' ? 'ascending' : active === 'desc' ? 'descending' : 'none') : undefined}
                className={cn(
                  'sa:h-8 sa:overflow-hidden sa:border-b sa:border-border-subtle sa:py-1 sa:pr-2 sa:pl-1 sa:align-middle sa:font-medium',
                  c.align === 'right' && 'sa:text-right',
                  i === 0 && stickyFirst(cn(firstDataLeft, 'sa:bg-component-table-header')),
                )}
              >
                {c.sortable ? (
                  <button
                    type="button"
                    onClick={() => cycleSort(c.key)}
                    className={cn(
                      labelClass,
                      'sa:transition-colors sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out) sa:focus-visible:outline-none',
                      'sa:satin-hover:bg-bg-hover sa:satin-focus:bg-bg-hover sa:satin-focus:[box-shadow:0_0_0_2px_var(--action-focus-ring)]',
                    )}
                  >
                    <span className="sa:truncate">{c.header}</span>
                    {active && <SortIcon direction={active} />}
                  </button>
                ) : (
                  <span className={labelClass}>{c.header}</span>
                )}
              </th>
            )
          })}
        </tr>
      </thead>
      <tbody>
        {sortedRows.map((row, r) => {
          const isSelected = selected.includes(row.id)
          const rowBg = zebra && r % 2 === 1 ? 'sa:bg-component-table-zebra' : 'sa:bg-bg-card'
          return (
            <tr key={row.id} data-state={isSelected ? 'selected' : undefined} className={cn('sa:group/row', rowBg, rowHover)}>
              {selectable && (
                <td className={cn('sa:py-2 sa:pl-2 sa:align-middle', cellPosition(0, cellCount), stickyFirst(cn('sa:left-0', rowBg)))}>
                  <Checkbox
                    aria-label={`${labels.selectRow} ${r + 1}`}
                    checked={isSelected}
                    onCheckedChange={(v) =>
                      setSelected(v === true ? [...selected, row.id] : selected.filter((id) => id !== row.id))
                    }
                    className="sa:align-middle"
                  />
                </td>
              )}
              {columns.map((c, i) => {
                const content = c.cell ? c.cell(row) : ((row as Record<string, unknown>)[c.key] as React.ReactNode)
                const plain = typeof content === 'string' || typeof content === 'number'
                return (
                  <td
                    key={c.key}
                    className={cn(
                      'sa:h-10 sa:overflow-hidden sa:py-2 sa:pr-2.5 sa:pl-3 sa:align-middle sa:text-body sa:leading-(--sa-text-body--line-height) sa:text-text-default',
                      c.align === 'right' && 'sa:text-right',
                      cellPosition(i + (selectable ? 1 : 0), cellCount),
                      i === 0 && stickyFirst(cn(firstDataLeft, rowBg)),
                    )}
                  >
                    {plain ? (
                      <span className="sa:block sa:truncate">{content}</span>
                    ) : (
                      <div className={cn('sa:flex sa:min-w-0 sa:items-center sa:gap-1 sa:overflow-hidden', c.align === 'right' && 'sa:justify-end')}>
                        {content}
                      </div>
                    )}
                  </td>
                )
              })}
            </tr>
          )
        })}
      </tbody>
    </table>
  )

  return (
    <div
      data-slot="table"
      className={cn('sa:relative sa:overflow-hidden sa:rounded-xl sa:border sa:border-border-subtle sa:bg-bg-card', className)}
      {...props}
    >
      {scroll ? (
        <>
          <div className="sa:relative">
            <div
              ref={viewport}
              tabIndex={0}
              role="region"
              aria-label={label ? `${label}, scrolls sideways` : 'Table, scrolls sideways'}
              className="sa:overflow-x-auto sa:[scrollbar-width:none] sa:focus-visible:outline-none sa:[&::-webkit-scrollbar]:hidden"
            >
              {table}
            </div>
            <div
              aria-hidden
              className={cn(
                'sa:pointer-events-none sa:absolute sa:inset-y-0 sa:right-0 sa:w-16 sa:bg-linear-to-r sa:from-bg-card-fade sa:to-bg-card',
                'sa:transition-opacity sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
                bar.atEnd && 'sa:opacity-0',
              )}
            />
          </div>
          <div aria-hidden className="sa:px-3 sa:pt-1.5 sa:pb-1">
            <div className="sa:relative sa:h-1.5 sa:overflow-hidden sa:rounded-full sa:bg-bg-muted">
              <div
                className="sa:absolute sa:inset-y-0 sa:left-0 sa:rounded-full sa:bg-border-strong"
                style={{ width: `${bar.size * 100}%`, transform: `translateX(${(bar.offset / bar.size) * 100}%)` }}
              />
            </div>
          </div>
        </>
      ) : (
        <div className="sa:overflow-x-auto sa:overscroll-x-contain">{table}</div>
      )}
    </div>
  )
}
